<?php
$categories=$db->query("SELECT id_kategori,nama_kategori FROM tbl_kategori WHERE status_kategori='aktif' ORDER BY nama_kategori")->fetchAll();
$products=$db->query("SELECT p.id_produk,p.sku,p.nama_produk,p.harga_jual,p.stok,p.satuan,p.gambar,p.id_kategori,k.nama_kategori FROM tbl_produk p JOIN tbl_kategori k ON k.id_kategori=p.id_kategori WHERE p.status_produk='aktif' AND p.stok>0 ORDER BY p.nama_produk")->fetchAll();
$customers=$db->query("SELECT id_pelanggan,no_member,nama_pelanggan FROM tbl_pelanggan WHERE status_member='aktif' ORDER BY nama_pelanggan")->fetchAll();
?>
